css:
.print-canvas { position: relative; width: 1056px; height: 816px; background-color: var(--ps-surface-base); box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1); overflow: hidden; }
@media print {
  @page { size: landscape; margin: 0; }
  body { padding: 0; margin: 0; background: var(--ps-surface-base); -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .print-canvas { box-shadow: none; width: 1056px; height: 816px; page-break-after: avoid; }
}
svg { shape-rendering: geometricPrecision; }
path { shape-rendering: crispEdges; }
marker path { shape-rendering: geometricPrecision; }
